import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.B_qehzBO.js";var i=JSON.parse(`{"title":"Hermes Stack: One Click, a Whole AI Server","description":"The story of Hermes Stack — turning one free Hugging Face Space into a personal AI server with an agent, routers, a dashboard and Telegram control.","frontmatter":{"title":"Hermes Stack: One Click, a Whole AI Server","description":"The story of Hermes Stack — turning one free Hugging Face Space into a personal AI server with an agent, routers, a dashboard and Telegram control."},"headers":[],"relativePath":"en/vibe-stories/story-2/index.md","filePath":"en/vibe-stories/story-2/index.md"}`),a={name:`en/vibe-stories/story-2/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="hermes-stack-one-click-a-whole-ai-server" tabindex="-1">Hermes Stack: One Click, a Whole AI Server <a class="header-anchor" href="#hermes-stack-one-click-a-whole-ai-server" aria-label="Permalink to “Hermes Stack: One Click, a Whole AI Server”">​</a></h1><p>A personal AI server usually means a VPS bill, a domain, a reverse proxy and a lost weekend. I wanted the same power for <strong>$0</strong> — so I built <strong><a href="https://github.com/Godde3s/hermes-stack" target="_blank" rel="noreferrer">Hermes Stack</a></strong>: a deploy kit that turns one free Hugging Face Space into a complete, always-on AI node.</p><h2 id="what-lands-on-the-space" tabindex="-1">What lands on the Space <a class="header-anchor" href="#what-lands-on-the-space" aria-label="Permalink to “What lands on the Space”">​</a></h2><p>One wizard — CLI, guided prompts or a GitHub Actions button — provisions a Space running three cooperating pieces: the <a href="https://github.com/NousResearch/hermes-agent" target="_blank" rel="noreferrer">Hermes agent</a> for multi-step task execution, <a href="https://github.com/decolua/9router" target="_blank" rel="noreferrer">9Router</a> for provider aggregation and my own <a href="https://github.com/Godde3s/omnirouter" target="_blank" rel="noreferrer">OmniRouter</a> for model routing — behind a web dashboard and an OpenAI-compatible API.</p><h2 id="the-parts-nobody-tells-you-about" tabindex="-1">The parts nobody tells you about <a class="header-anchor" href="#the-parts-nobody-tells-you-about" aria-label="Permalink to “The parts nobody tells you about”">​</a></h2><ul><li><strong>Keep-alive that respects the platform</strong> — a gentle ping loop keeps the free Space awake without hammering it.</li><li><strong>Hourly backups with real restore</strong> — state is snapshotted somewhere you own; a rebuild rehydrates instead of starting over.</li><li><strong>Telegram as a control plane</strong> — restart, redeploy, check status and tail logs from your phone.</li><li><strong>Dry-run honesty</strong> — the wizard previews every step before touching your account, and works with placeholders until you wire real secrets.</li></ul><h2 id="what-it-proves" tabindex="-1">What it proves <a class="header-anchor" href="#what-it-proves" aria-label="Permalink to “What it proves”">​</a></h2><p>Hermes Stack is DevOps empathy encoded in Python: idempotent provisioning, observable runtime, boring, recoverable failure. It is the project friends ask me to walk them through — and the fastest way to understand how I think about deployment: <strong>if it is not reproducible from scratch, it is not deployed.</strong></p>`,8)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};